insert into public.lib_techniques (id, discipline_id, category_id, position, name, aliases, source_text, proposed_text, origin, level, validation_refs, restricted, uzu_links, source, archived) values
  ('G01', 'jjb_gi', 'jjb_gi_1', 1, 'Ankle Pick (Saisie de cheville)', '{}'::text[], 'Casser la posture de l''adversaire par une forte traction vers le bas sur le col croisé (main droite au col gauche). Abaisser simultanément son propre niveau en fléchissant les jambes pour venir bloquer la cheville située du même côté (cheville gauche avec la main gauche) et pousser l''épaule vers l''arrière.', null, 'document', null, array['V1']::text[], null, '["sys:lutte:Takedowns"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G02', 'jjb_gi', 'jjb_gi_1', 2, 'Projections en sacrifice (Tomoe Nage / Sumi Gaeshi)', array['Tomoe Nage','Sumi Gaeshi']::text[], 'Idéales lorsque l''adversaire adopte une posture très basse et défensive. Saisir le col et la manche, s''asseoir près de ses pieds en plaçant un pied sur sa hanche (Tomoe Nage) ou un crochet papillon à l''intérieur de sa cuisse (Sumi Gaeshi) pour le projeter par-dessus soi en roulant sur le dos.', null, 'document', null, array['V2','S2']::text[], null, '["sys:lutte:Takedowns"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G03', 'jjb_gi', 'jjb_gi_1', 3, 'Single Leg (Saisie à une jambe) avec saisie du col', '{}'::text[], 'Saisir le col pour tirer l''adversaire vers soi et alourdir sa jambe avant. Changer de niveau, envelopper sa cuisse avec les deux bras (tête collée à l''intérieur de ses côtes) et pivoter pour le faire chuter tout en gardant le contrôle du kimono pour l''empêcher de reculer.', null, 'document', null, array['V3']::text[], null, '["sys:lutte:Takedowns"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G04', 'jjb_gi', 'jjb_gi_1', 4, 'Pull Guard vers Collar-Sleeve (Tirage de garde Col-Manche)', array['Col-Manche']::text[], 'Saisir fermement le col croisé et la manche opposée pour contrôler la distance. S''asseoir au sol en plaçant immédiatement le pied côté manche sur sa hanche et l''autre pied dans le creux de son épaule pour créer une tension constante.', null, 'document', null, array['V4']::text[], null, '["sys:fond"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G05', 'jjb_gi', 'jjb_gi_1', 5, 'Guard Pull vers De La Riva (Tirage de garde DLR)', array['DLR']::text[], 'Saisir le col et la manche (ou le bas du pantalon) pour s''asseoir sur la hanche. Engager immédiatement le crochet De La Riva derrière son genou avant en enroulant la jambe de l''extérieur vers l''intérieur, tout en plaçant l''autre pied sur sa hanche opposée.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G06', 'jjb_gi', 'jjb_gi_2', 1, 'Garde Collar-Sleeve (Col-Manche)', '{}'::text[], 'Maintenir une traction diagonale forte (col croisé et manche opposée) couplée à un pied sur la hanche et un pied dans l''épaule. Cette tension constante casse la posture du passeur, crée des angles de sortie de hanche et ouvre directement les attaques en triangle ou omoplata.', null, 'document', null, array['V4']::text[], null, '["sys:fond"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G07', 'jjb_gi', 'jjb_gi_2', 2, 'De La Riva (DLR) vers Berimbolo', array['Berimbolo']::text[], 'Utiliser le crochet De La Riva et le contrôle de la cheville pour forcer l''adversaire à poser ses fesses au tapis. S''inverser ensuite sous ses hanches (en roulant sur les épaules, jamais sur la nuque) pour saisir sa ceinture ou son pantalon et remonter directement dans son dos.', null, 'document', null, array['T2']::text[], null, '["tech:sw-berimbolo"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G08', 'jjb_gi', 'jjb_gi_2', 3, 'Lasso Guard et Spider-Lasso', array['Spider-Lasso','Spider Guard']::text[], 'Passer sa jambe par-dessus le bras de l''adversaire et enrouler le mollet autour de son biceps en calant le pied sous son aisselle (Lasso). Coupler ce verrouillage avec un pied en poussée sur l''autre biceps (Spider) pour neutraliser totalement les passeurs rapides.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G09', 'jjb_gi', 'jjb_gi_2', 4, 'Lapel Guard (Garde avec revers : Worm Guard / Squid Guard)', array['Worm Guard','Squid Guard']::text[], 'Défaire le bas de la veste de l''adversaire et le passer derrière son genou ou entre ses jambes pour le récupérer avec sa main libre. Ce lien en tissu immobilise sa jambe d''appui, bloque sa mobilité latérale et offre des leviers puissants pour le renverser.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G10', 'jjb_gi', 'jjb_gi_2', 5, 'Reverse De La Riva (RDLR) avec Kiss of the Dragon', array['Kiss of the Dragon','RDLR']::text[], 'Face à un adversaire qui tente un Knee Cut, placer un crochet inversé à l''intérieur de sa cuisse avant et saisir sa cheville. S''inverser sous son centre de gravité en plongeant la tête sous sa hanche pour exposer son dos et prendre ses crochets.', null, 'document', null, array['S3']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G11', 'jjb_gi', 'jjb_gi_2', 6, 'Rétention par Granby Roll et cadrage (Framing)', array['Granby Roll','Framing']::text[], 'Dès que le passeur franchit la ligne des pieds, utiliser la structure osseuse des avant-bras (frames) sur son cou et sa hanche pour stopper sa progression. Rouler ensuite d''une épaule à l''autre (Granby Roll) en gardant les genoux groupés vers la poitrine pour replacer ses tibias devant lui.', null, 'document', null, array['S3']::text[], null, '["sys:fond:Rétention de garde"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G12', 'jjb_gi', 'jjb_gi_3', 1, 'Tripod Sweep (Renversement trépied) et Sickle Sweep (Renversement faucille)', array['Sickle Sweep']::text[], 'Face à un adversaire debout, contrôler sa manche et sa cheville. Placer un pied sur sa hanche et l''autre derrière son genou pour le faire tomber en arrière (Tripod). S''il recule la jambe attaquée, faucher immédiatement son autre cheville au ras du tapis (Sickle).', null, 'document', null, array['V5']::text[], null, '["tech:sw-tripod"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G13', 'jjb_gi', 'jjb_gi_3', 2, 'Scissor Sweep (Renversement ciseau)', '{}'::text[], 'Depuis la garde fermée ou ouverte, saisir le col et la manche, puis effectuer un décalage de hanche (langouste) pour créer un angle. Placer un tibia en travers de son abdomen et l''autre jambe au ras du sol pour faucher son genou d''appui tout en tirant sur ses bras.', null, 'document', null, '{}'::text[], null, '["tech:sw-scissor"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G14', 'jjb_gi', 'jjb_gi_3', 3, 'Waiter Sweep (Renversement du serveur depuis la Deep Half Guard)', array['Deep Half Guard']::text[], 'Se glisser profondément sous les hanches de l''adversaire en enveloppant sa cuisse. Soulever sa jambe comme un plateau de serveur tout en le déséquilibrant vers l''arrière pour le faire basculer et remonter en position dominante.', null, 'document', null, array['V6']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G15', 'jjb_gi', 'jjb_gi_3', 4, 'Overhead Sweep (Tomoe Nage depuis la garde)', '{}'::text[], 'Lorsque l''adversaire met beaucoup de pression vers l''avant, saisir le col et une manche (ou les deux manches). Placer les deux pieds sur ses hanches, se laisser rouler sur le dos et déployer les jambes vers le haut pour le projeter par-dessus soi.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G16', 'jjb_gi', 'jjb_gi_3', 5, 'Berimbolo / Crab Ride vers prise de dos', array['Crab Ride']::text[], 'Après avoir déséquilibré l''adversaire au sol, utiliser le Crab Ride (crochets placés derrière ses genoux et contrôle ferme des hanches/pantalon) pour le maintenir assis. Grimper ensuite le long de son buste pour sécuriser la ceinture de sécurité (Seatbelt) et les crochets.', null, 'document', null, array['T2']::text[], null, '["tech:sw-berimbolo"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G17', 'jjb_gi', 'jjb_gi_4', 1, 'Torreando Pass (Passage du torero)', array['Toreando']::text[], 'Saisir le bas du pantalon au niveau des chevilles, tendre les bras pour contrôler ses jambes et les jeter d''un côté. Contourner immédiatement sa hanche en venant coller son épaule ou sa tête sur son torse pour l''empêcher de revenir face à vous.', null, 'document', null, '{}'::text[], null, '["tech:gp-toreando"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G18', 'jjb_gi', 'jjb_gi_4', 2, 'Knee Cut Pass (Passage en coupant le genou)', array['Knee Slice']::text[], 'Ouvrir la garde, poser un genou au centre et glisser le tibia en diagonale par-dessus sa cuisse jusqu''au tapis. Sécuriser simultanément un underhook (bras sous son aisselle) et tirer sa manche opposée vers le haut pour plaquer ses épaules au sol.', null, 'document', null, '{}'::text[], null, '["tech:gp-kneeslice"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G19', 'jjb_gi', 'jjb_gi_4', 3, 'Leg Drag Pass', '{}'::text[], 'Saisir la cheville et le genou de l''adversaire pour dévier sa jambe en travers de sa propre hanche. Bloquer sa jambe avec sa propre hanche pour l''empêcher de la retirer, tout en saisissant son col pour fixer le haut de son corps et passer sur le côté.', null, 'document', null, array['V7']::text[], null, '["tech:gp-legdrag"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G20', 'jjb_gi', 'jjb_gi_4', 4, 'Over-Under Pass', '{}'::text[], 'Passer un bras par-dessus une jambe (en saisissant la hanche) et l''autre bras par-dessous l''autre jambe (en la calant sur son épaule). Coller sa tête contre ses côtes pour éviter les étranglements, marcher sur le côté et dégager sa jambe piégée.', null, 'document', null, '{}'::text[], null, '["tech:gp-overunder"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G21', 'jjb_gi', 'jjb_gi_4', 5, 'Double Under Pass (Stack Pass)', array['Stack Pass']::text[], 'Passer les deux bras sous les cuisses de l''adversaire et joindre les mains ou saisir ses revers. Avancer les hanches pour l''empiler sur ses épaules (le plier en deux), puis faire basculer ses jambes sur le côté pour stabiliser le contrôle latéral.', null, 'document', null, array['S2']::text[], null, '["tech:gp-doubleund"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G22', 'jjb_gi', 'jjb_gi_4', 6, 'Long Step Pass (Passage en grand pas)', '{}'::text[], 'Face à une demi-garde ou une garde De La Riva, saisir fermement le col et le pantalon. Effectuer un grand pas circulaire vers l''arrière avec la jambe libre pour extraire le pied piégé, tout en gardant la tête basse et la pression sur le haut du corps.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G23', 'jjb_gi', 'jjb_gi_5', 1, 'Contrôle du dos (Seatbelt ou prise de col croisée)', array['Seatbelt']::text[], 'Coller sa poitrine contre le dos de l''adversaire en engageant les deux talons à l''intérieur de ses cuisses (crochets). Verrouiller les mains en ceinture de sécurité (Seatbelt : un bras par-dessus l''épaule, l''autre sous l''aisselle) ou saisir son col croisé pour bloquer ses épaules.', null, 'document', null, '{}'::text[], null, '["sys:controle:Back attack"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G24', 'jjb_gi', 'jjb_gi_5', 2, 'Crossface et contrôle de manche en position latérale (Side Control)', array['Crossface','Side Control']::text[], 'Passer un bras sous la nuque de l''adversaire pour appliquer une forte pression de l''épaule sur sa mâchoire (Crossface) et tourner sa tête. Avec l''autre main, contrôler sa manche éloignée ou sa hanche pour neutraliser toute tentative de langouste.', null, 'document', null, '{}'::text[], null, '["sys:fond:Contrôle latéral et monte"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G25', 'jjb_gi', 'jjb_gi_5', 3, 'Elbow-Knee Escape (Langouste) avec cadrage', array['Langouste','Shrimp']::text[], 'Sous la pression latérale, placer un avant-bras en cadre contre le cou du passeur et l''autre contre sa hanche pour créer de l''espace. Pousser sur ses pieds pour sortir les hanches vers l''arrière (langouste) et glisser le genou inférieur entre vous deux pour récupérer la garde.', null, 'document', null, '{}'::text[], null, '["sys:fond:Sorties de monte et contrôle latéral"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G26', 'jjb_gi', 'jjb_gi_5', 4, 'Half Guard Knee Shield (Demi-garde bouclier) vers boucle de revers', array['Knee Shield']::text[], 'En demi-garde, placer son tibia supérieur en diagonale contre le torse du passeur pour maintenir la distance. Défaire son revers, le passer sous son bras pour le saisir et neutraliser sa posture, puis remonter sur un coude en position Dogfight.', null, 'document', null, array['V8']::text[], null, '["sys:fond:Demi-garde"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G27', 'jjb_gi', 'jjb_gi_6', 1, 'Bow and Arrow Choke (Étranglement arc et flèche)', '{}'::text[], 'Depuis le dos avec une prise profonde au col, saisir le pantalon de l''adversaire au niveau du genou avec l''autre main. Basculer sur le côté, passer la jambe par-dessus son épaule pour bloquer son bras et tirer simultanément sur le col et la jambe comme pour bander un arc.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G28', 'jjb_gi', 'jjb_gi_6', 2, 'Cross Collar Choke (Étranglement croisé)', '{}'::text[], 'Depuis la garde fermée ou la position montée, glisser une main profondément derrière le col (pouce à l''intérieur). Glisser la seconde main par-dessous ou par-dessus la première pour saisir l''autre côté du col, puis effectuer une rotation des poignets en ramenant les coudes vers les hanches.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G29', 'jjb_gi', 'jjb_gi_6', 3, 'Loop Choke (Étranglement en boucle)', '{}'::text[], 'Saisir le col de l''adversaire (pouce à l''intérieur) et l''inciter à baisser la tête. Passer son autre bras sous sa tête pour envelopper sa nuque, glisser la main derrière son épaule et lever le coude du bras qui tient le col pour fermer la boucle autour de sa gorge.', null, 'document', null, array['V9']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G30', 'jjb_gi', 'jjb_gi_6', 4, 'Enchaînement Triangle et Armbar (Clé de bras)', array['Triangle','Armbar']::text[], 'Depuis la garde fermée ou Col-Manche, tirer une manche vers soi tout en repoussant l''autre bras pour créer un déséquilibre (un bras dedans, un bras dehors). Verrouiller le triangle avec les jambes ; si l''adversaire se redresse pour défendre, pivoter à 90 degrés et passer la jambe sur son visage pour finir en clé de bras.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N01', 'grappling_nogi', 'grappling_nogi_1', 1, 'Snap Down vers Front Headlock', array['Front Headlock']::text[], 'Casser la posture de l''adversaire par des tractions sèches sur la nuque et les poignets pour amener ses mains au tapis. Enchaîner immédiatement en contrôlant sa tête sous son aisselle et son bras opposé (Front Headlock) pour attaquer le dos ou un étranglement.', null, 'document', null, '{}'::text[], null, '["sys:lutte:Snap down","sys:controle:Front headlock"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N02', 'grappling_nogi', 'grappling_nogi_1', 2, 'Single Leg (Saisie à une jambe) avec finition Run the Pipe', array['Run the Pipe']::text[], 'Changer de niveau, saisir la jambe avant avec les deux mains et coller son oreille contre les côtes de l''adversaire pour éviter la guillotine. Pivoter en cercle vers l''arrière tout en poussant la tête contre son buste (Run the Pipe) pour le faire chuter.', null, 'document', null, '{}'::text[], null, '["sys:lutte:Takedowns"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N03', 'grappling_nogi', 'grappling_nogi_1', 3, 'Arm Drag (Décalage de bras debout ou assis) vers prise de dos', array['Arm Drag']::text[], 'Saisir le poignet de l''adversaire avec une main et venir frapper/tirer l''arrière de son triceps avec l''autre main pour traverser son bras devant lui. Glisser immédiatement derrière son épaule pour coller sa poitrine à son dos et verrouiller la taille.', null, 'document', null, '{}'::text[], null, '["sys:lutte:Takedowns"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N04', 'grappling_nogi', 'grappling_nogi_1', 4, 'Body Lock Takedown (Ceinture arrière ou avant)', array['Body Lock']::text[], 'Fermer les mains autour de la taille de l''adversaire en gardant la tête collée sous son menton ou sur sa poitrine. Lever ses hanches pour le déraciner du sol, puis le faire basculer sur le côté en tombant en contrôle latéral.', null, 'document', null, array['S2']::text[], null, '["sys:lutte:Takedowns"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N05', 'grappling_nogi', 'grappling_nogi_1', 5, 'Slide By (Décalage de bras sur poussée)', '{}'::text[], 'Lorsque l''adversaire exerce une pression vers l''avant avec son bras sur votre nuque, saisir son poignet, lever le coude et glisser votre tête sous son aisselle. Pivoter rapidement dans son dos en utilisant son propre élan vers l''avant.', null, 'document', null, '{}'::text[], null, '["sys:lutte:Transitions dynamiques"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N06', 'grappling_nogi', 'grappling_nogi_2', 1, 'Seated Guard (Garde assise) avec Hand Fighting', array['Hand Fighting']::text[], 'Rester assis le buste incliné vers l''avant (jamais allongé sans contact) en gardant les coudes serrés. Engager une bataille de mains constante pour contrôler les poignets et la nuque de l''adversaire afin d''empêcher ses entrées en passage.', null, 'document', null, '{}'::text[], null, '["sys:lutte:Hand-fighting"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N07', 'grappling_nogi', 'grappling_nogi_2', 2, 'Butterfly Guard (Garde papillon)', '{}'::text[], 'Assis face à l''adversaire, insérer les deux pieds à l''intérieur de ses cuisses (crochets papillon). Rester actif sur les fesses pour contrôler le haut de son corps (underhooks ou contrôle de nuque) et se glisser sous son centre de gravité.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N08', 'grappling_nogi', 'grappling_nogi_2', 3, 'Single Leg X (SLX / Ashi Garami)', array['SLX','Ashi Garami']::text[], 'S''insérer sous l''adversaire debout en plaçant un pied sur sa hanche et l''autre jambe enroulée autour de sa cuisse, genoux serrés autour de son genou. Cette structure isole sa jambe, le déséquilibre vers l''arrière et ouvre les clés de cheville ou de talon.', null, 'document', null, array['V10','S1']::text[], null, '["sys:jambes:Entrées de leglocks"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N09', 'grappling_nogi', 'grappling_nogi_2', 4, 'Demi-garde avec Knee Shield (Bouclier de genou / Z-Guard)', array['Z-Guard']::text[], 'Sur le côté, placer son tibia supérieur en diagonale devant le torse du passeur pour bloquer sa pression. Garder un contrôle sur son poignet et son épaule pour créer l''espace nécessaire afin de glisser un underhook ou attaquer les jambes.', null, 'document', null, '{}'::text[], null, '["sys:fond:Demi-garde"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N10', 'grappling_nogi', 'grappling_nogi_2', 5, 'K-Guard', '{}'::text[], 'Depuis la garde fermée ou ouverte, pivoter sur l''épaule pour passer une jambe sous l''aisselle de l''adversaire et saisir son talon. Cette position permet de passer sous sa jambe d''appui pour entrer directement en Backside 50/50 (clé de talon) ou prendre son dos.', null, 'document', null, array['V11','S1']::text[], null, '["sys:jambes:Entrées de leglocks"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N11', 'grappling_nogi', 'grappling_nogi_2', 6, 'Rétention par Supine Guard et High Pummel', array['Supine Guard','High Pummel']::text[], 'Sur le dos face à un passeur rapide, garder les genoux collés à la poitrine pour fermer l''espace interne. Utiliser le High Pummel (passer ses pieds par-dessus les bras du passeur) pour replacer ses pieds sur ses épaules et ses hanches sans aucun grip.', null, 'document', null, '{}'::text[], null, '["sys:fond:Rétention de garde"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N12', 'grappling_nogi', 'grappling_nogi_3', 1, 'Butterfly Sweep (Sumi Gaeshi avec underhook)', '{}'::text[], 'Depuis la garde papillon, sécuriser un underhook profond d''un côté et contrôler le coude ou le poignet de l''autre. Tomber sur l''épaule côté bras bloqué tout en soulevant l''adversaire avec le crochet papillon opposé pour le renverser en position montée.', null, 'document', null, '{}'::text[], null, '["tech:sw-butterfly"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N13', 'grappling_nogi', 'grappling_nogi_3', 2, 'Wrestle-Up depuis la garde assise (Single Leg)', array['Technical Stand-Up']::text[], 'Dès que l''adversaire recule ou rompt le contact pour éviter votre garde, poser une main au sol derrière soi et se relever explosivement (Technical Stand-Up). Venir cueillir sa cheville ou son genou avant pour terminer en Single Leg.', null, 'document', null, '{}'::text[], null, '["sys:lutte:Wrestle-up"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N14', 'grappling_nogi', 'grappling_nogi_3', 3, 'Arm Drag depuis la garde assise vers prise de dos ou renversement', '{}'::text[], 'Tirer le poignet et le triceps de l''adversaire en travers de votre buste pour exposer son dos. Glisser les hanches sur le côté pour grimper dans son dos, ou crocheter sa jambe d''appui s''il résiste pour le faire tomber en arrière.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N15', 'grappling_nogi', 'grappling_nogi_3', 4, 'John Wayne Sweep (Giggler)', array['Giggler']::text[], 'Depuis la demi-garde, bloquer le poignet du passeur contre votre buste pour l''empêcher de se rattraper au sol. Utiliser le genou inférieur pour lever son genou vers l''extérieur tout en basculant sur le côté, ce qui crée un effet de levier imparable pour le renverser.', null, 'document', null, array['V12']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N16', 'grappling_nogi', 'grappling_nogi_3', 5, 'Lockdown vers Electric Chair Sweep', array['Lockdown','Electric Chair']::text[], 'En demi-garde à plat, verrouiller la jambe de l''adversaire en enroulant vos deux jambes autour de la sienne (Lockdown). Étirer sa jambe pour casser sa base, plonger sous son centre de gravité en contrôlant sa cuisse opposée et le basculer vers l''avant (Electric Chair).', null, 'document', null, array['V13']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N17', 'grappling_nogi', 'grappling_nogi_4', 1, 'Body Lock Pass', '{}'::text[], 'S''approcher au corps à corps, verrouiller ses mains autour des hanches de l''adversaire et poser la tête sur son sternum. Écraser ses jambes avec son propre poids, dégager un genou puis l''autre par-dessus ses tibias pour stabiliser le contrôle latéral.', null, 'document', null, '{}'::text[], null, '["tech:gp-bodylock"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N18', 'grappling_nogi', 'grappling_nogi_4', 2, 'Knee Cut Pass avec Underhook et contrôle de tête', array['Knee Slice']::text[], 'Ouvrir la garde, poser un genou au centre et glisser le tibia en diagonale par-dessus sa cuisse. Gagner impérativement l''espace sous son aisselle (underhook) et contrôler sa tête avec l''autre bras pour coller ses épaules au tapis.', null, 'document', null, '{}'::text[], null, '["tech:gp-kneeslice"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N19', 'grappling_nogi', 'grappling_nogi_4', 3, 'Camping / J-Point Camping', '{}'::text[], 'Bloquer les hanches de l''adversaire en se plaçant sur le côté avec une forte pression de l''épaule et des mains. Maintenir cette position d''attente (Camping) pour épuiser ses muscles abdominaux et fléchisseurs de hanche avant de contourner définitivement sa garde.', null, 'document', null, array['V14']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N20', 'grappling_nogi', 'grappling_nogi_4', 4, 'Loose Pass / Torreando No-Gi (Passage à distance)', array['Toreando']::text[], 'Saisir l''arrière des chevilles ou des tibias en gardant les bras tendus pour maintenir la distance. Dévier rapidement ses jambes d''un côté tout en se déplaçant à l''opposé vers sa tête pour contourner ses hanches sans entrer dans sa garde.', null, 'document', null, '{}'::text[], null, '["tech:gp-toreando"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N21', 'grappling_nogi', 'grappling_nogi_4', 5, 'Leg Drag Pass (avec contrôle de hanche)', '{}'::text[], 'Saisir la cheville et le genou de l''adversaire pour faire traverser sa jambe devant sa propre hanche. Bloquer immédiatement sa hanche opposée avec sa main libre ou son genou pour l''empêcher de se tourner et stabiliser le passage.', null, 'document', null, '{}'::text[], null, '["tech:gp-legdrag"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N22', 'grappling_nogi', 'grappling_nogi_4', 6, 'Smash Pass (depuis Headquarters)', array['Headquarters']::text[], 'Depuis la position Headquarters (un pied au centre entre ses jambes), plier les deux genoux de l''adversaire sur un même côté en écrasant ses cuisses avec son poids. Contrôler sa tête ou son épaule éloignée pour l''empêcher de faire la langouste et passer en position latérale.', null, 'document', null, array['F2']::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N23', 'grappling_nogi', 'grappling_nogi_5', 1, 'Back Control avec Body Triangle et Hand Fighting', array['Body Triangle','Straight Jacket']::text[], 'Verrouiller un triangle autour de la taille de l''adversaire (Body Triangle) pour immobiliser ses hanches. Utiliser le Hand Fighting pour piéger l''un de ses bras avec sa propre jambe (Straight Jacket) et isoler son cou.', null, 'document', null, array['V15']::text[], null, '["sys:controle:Back attack"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N24', 'grappling_nogi', 'grappling_nogi_5', 2, 'Half Guard vers Dogfight (Underhook battle)', array['Dogfight']::text[], 'Depuis la demi-garde, glisser un underhook profond sous l''aisselle du passeur et se redresser sur un coude puis sur les genoux (Dogfight). Pousser vers l''adversaire pour le renverser ou pivoter derrière lui pour prendre son dos.', null, 'document', null, '{}'::text[], null, '["sys:fond:Demi-garde"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N25', 'grappling_nogi', 'grappling_nogi_5', 3, 'Heel Slip (Extraction du talon)', '{}'::text[], 'Dès qu''une clé de talon est engagée, pousser sur la hanche de l''adversaire avec le pied libre, tourner le genou vers l''extérieur pour libérer la ligne du genou et faire glisser son talon hors de la prise de son aisselle.', 'Sortir avant que la prise se ferme : dès que l''adversaire va chercher le talon, cacher le talon, dégager la ligne du genou (amener son genou au-delà des hanches de l''adversaire), pousser sur sa hanche avec le pied libre et retirer la jambe en ligne droite, sans rotation, hors de son aisselle. Sécurité : si la clé est déjà serrée, ne pas tourner, taper. Aucune consigne de rotation tant qu''un professeur ne l''a pas précisée selon la clé (interne ou externe).', 'document', null, array['V16','S1']::text[], 'cles_talon', '["sys:jambes"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N26', 'grappling_nogi', 'grappling_nogi_5', 4, 'Kipping Escape (Évasion par bascule du bassin)', array['Kipping']::text[], 'Sous la position montée ou latérale sans friction de kimono, placer ses mains en cadre sur les hanches du passeur. Effectuer des mouvements explosifs de flexion-extension du bassin (Kipping) pour soulever son poids et réinsérer ses genoux.', null, 'document', null, '{}'::text[], null, '["sys:fond:Sorties de monte et contrôle latéral"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N27', 'grappling_nogi', 'grappling_nogi_6', 1, 'Rear Naked Choke (Mata Leão à une main)', array['RNC','Mata Leão']::text[], 'Une fois un bras de l''adversaire piégé par vos jambes, glisser l''avant-bras sous son menton en alignant le coude avec sa trachée. Placer la main derrière sa nuque (sans avoir besoin du second bras) et serrer le coude vers l''épaule pour couper la circulation.', 'Glisser l''avant-bras sous son menton, le pli du coude centré sous le menton, le biceps et l''avant-bras de part et d''autre du cou. Version à une main (son bras piégé) : la main du bras qui étrangle saisit votre épaule opposée, l''autre main contrôle sa tête ou son poignet. Serrer en rapprochant le coude, tête collée contre la sienne. Sécurité : pas de pression sur la trachée. Étranglement sanguin : la perte de connaissance peut survenir en quelques secondes. Serrer progressivement, relâcher immédiatement au premier tap ou si le partenaire ne répond plus.', 'document', null, array['V17']::text[], null, '["sys:controle:RNC / étranglement arrière"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N28', 'grappling_nogi', 'grappling_nogi_6', 2, 'Inside Heel Hook (Clé de talon interne)', array['Heel Hook']::text[], 'Depuis le Saddle (4/11) ou le 50/50, immobiliser le genou de l''adversaire entre ses cuisses. Caler son talon dans le creux de votre poignet (pouce vers le haut), coller votre poitrine sur sa cheville et effectuer une rotation contrôlée en arquant le dos.', 'Depuis le Saddle (N32) ou le Backside 50/50 (N33) : genou de l''adversaire bloqué entre vos cuisses, genoux serrés. Son talon calé dans le creux du poignet, ses orteils coincés sous votre aisselle, mains jointes paume contre paume. Rotation lente du buste qui entraîne le talon, sans à-coup. Sécurité : application très lente, arrêt au premier tap. Le partenaire doit taper tôt, car la douleur arrive souvent après la lésion. Réservée aux pratiquants avancés, et seulement dans les règles et catégories qui l''autorisent.', 'document', null, array['V18','S1']::text[], 'cles_talon', '["sys:jambes:Clés de talon / cheville / genou"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N29', 'grappling_nogi', 'grappling_nogi_6', 3, 'Guillotine (High Elbow) et Darce Choke', array['Guillotine','Darce']::text[], 'Sur un adversaire qui baisse la tête, envelopper sa nuque en remontant le coude très haut sur son dos (High Elbow Guillotine) pour bloquer sa sortie. S''il tourne sur le côté pour défendre, glisser le bras sous son aisselle et verrouiller sur votre propre biceps (Darce Choke).', null, 'document', null, '{}'::text[], null, '["sys:controle:Guillotine / Anaconda"]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('N30', 'grappling_nogi', 'grappling_nogi_6', 4, 'Arm Triangle (Kata Gatame)', array['Kata Gatame']::text[], 'Depuis la position montée ou latérale, isoler un bras de l''adversaire en travers de sa propre gorge avec votre épaule. Descendre sur le côté (côté opposé au bras piégé), verrouiller vos mains paume contre paume et mettre la pression de l''épaule en abaissant les hanches.', null, 'document', null, '{}'::text[], null, '[]'::jsonb, 'Programme technique JJB Gi & No-Gi (document fourni par le club)', false),
  ('G31', 'jjb_gi', 'jjb_gi_6', 5, 'Omoplata (Clé d''épaule avec les jambes)', '{}'::text[], null, 'Depuis Col-Manche, contrôler la manche, pivoter les hanches et passer la jambe par-dessus son épaule. S''asseoir face à ses jambes, bloquer sa hanche pour l''empêcher de rouler, puis pencher le buste vers l''avant. Sécurité : pression lente, l''épaule cède vite ; si le partenaire roule pour s''échapper, le laisser rouler.', 'proposition', 2, array['F1']::text[], null, '[]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('G32', 'jjb_gi', 'jjb_gi_4', 7, 'Headquarters (Position de départ du passage)', '{}'::text[], null, 'Un genou entre ses jambes, l''autre pied à l''extérieur, contrôle du pantalon et du col. Hanches basses, poids sur la jambe qui écrase sa cuisse. Position d''attente d''où partent le Torreando et le Knee Cut.', 'proposition', 1, array['F2']::text[], null, '[]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('G33', 'jjb_gi', 'jjb_gi_5', 5, 'Passage en montée (Mount)', '{}'::text[], null, 'Depuis le contrôle latéral, garder le Crossface, bloquer sa hanche avec la main, glisser le genou sur son ventre puis le passer de l''autre côté. S''installer genoux serrés contre ses côtes, pieds crochetés sous ses jambes.', 'proposition', 1, array['F2']::text[], null, '["sys:fond:Contrôle latéral et monte"]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('G34', 'jjb_gi', 'jjb_gi_4', 8, 'Smash Pass en kimono', '{}'::text[], null, 'Même principe que N22 : plaquer ses deux jambes au sol, l''une sur l''autre, épaule sur sa hanche, puis contourner. En kimono, tenir le pantalon pour garder les jambes collées. Sécurité : ne pas tordre son genou en écrasant.', 'proposition', 2, array['F2']::text[], null, '[]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('N31', 'grappling_nogi', 'grappling_nogi_2', 7, 'X-Guard', '{}'::text[], null, 'Sous l''adversaire debout : un crochet derrière son genou, l''autre pied sur sa hanche, une main sur sa cheville. Étendre les jambes pour le faire basculer et l''obliger à poser les mains au tapis.', 'proposition', 2, array['F3']::text[], null, '["sys:jambes:Entrées de leglocks"]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('N32', 'grappling_nogi', 'grappling_nogi_2', 8, 'Saddle (4/11, Honey Hole)', array['4/11','Honey Hole','Inside Sankaku']::text[], null, 'Sa jambe entre les tiennes, ta jambe intérieure en travers de sa hanche, ta jambe extérieure par-dessus qui se verrouille derrière ton genou (forme en 4), genoux serrés. Contrôler le talon avant toute rotation. Sécurité : position des clés de talon, réservée aux pratiquants avancés et aux règles qui les autorisent.', 'proposition', 3, array['F3','S1']::text[], 'cles_talon', '["sys:jambes:Ashi garami"]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('N33', 'grappling_nogi', 'grappling_nogi_2', 9, 'Backside 50/50', array['50/50']::text[], null, 'Depuis la 50/50, passer derrière sa jambe pour que son talon soit exposé, contrôler son genou avant d''attaquer. Même sécurité que N32.', 'proposition', 3, array['F3','S1']::text[], 'cles_talon', '["sys:jambes:Ashi garami"]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('N34', 'grappling_nogi', 'grappling_nogi_5', 5, 'Crab Ride sans kimono', array['Crab Ride']::text[], null, 'Assis derrière ses hanches, un crochet à l''intérieur de sa cuisse, contrôle de sa hanche (pas de ceinture en No-Gi). Suivre ses déplacements pour remonter vers son dos. G16 reste la version kimono.', 'proposition', 3, array['F3']::text[], null, '["sys:controle:Back attack"]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('N35', 'grappling_nogi', 'grappling_nogi_5', 6, 'Dagestani Handcuff (Piège du bras en menottes)', array['Handcuff']::text[], null, 'Depuis le côté ou la tortue, saisir un bras de l''adversaire à deux mains pour le bloquer contre lui, puis rouler pour le mettre sur le dos avec le bras piégé, ce qui ouvre l''étranglement tête-bras. Description générale à préciser par un professeur.', 'proposition', 3, array['F4']::text[], null, '[]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true),
  ('N36', 'grappling_nogi', 'grappling_nogi_5', 7, 'Contrôle latéral Chest-to-Chest (No-Gi)', array['Chest-to-Chest','Side Control']::text[], null, 'Poitrine contre poitrine, bras sous sa nuque ou Crossface, underhook sur le bras éloigné, hanches basses, genoux collés contre lui pour bloquer la langouste.', 'proposition', 1, array['F4']::text[], null, '["sys:fond:Contrôle latéral et monte"]'::jsonb, 'Proposition UZU du 17/11/2026 — à valider par un professeur qualifié', true)
insert into public.lib_flows (id, discipline_id, position, title, intro) values
  ('FC1', 'jjb_gi', 1, 'Le système « Garde Ouverte vers Prise de Dos »', 'En kimono, tout part de la connexion à distance pour forcer l''adversaire à réagir, créant ainsi un accès à son dos.'),
  ('FC2', 'jjb_gi', 2, 'Le système « Passage de Garde en Dilemme »', 'Pour passer une garde moderne en kimono, il faut alterner entre vitesse (contourner) et pression (écraser).'),
  ('FC3', 'grappling_nogi', 3, 'Le système « Garde Assise, Wrestle-Up & Leg Locks »', 'En No-Gi, le joueur du dessous crée un dilemme constant entre le haut du corps (lutte) et le bas du corps (clés de jambes).'),
  ('FC4', 'grappling_nogi', 4, 'Le système « Lutte, Pression & Étranglements Tête-Bras »', 'Le jeu moderne du dessus en No-Gi consiste à fatiguer l''adversaire par la pression constante avant de verrouiller la tête et un bras.')
insert into public.lib_flow_steps (id, flow_id, position, parent_id, kind, branch_label, label, origin) values
  ('FC1-1', 'FC1', 1, null, 'depart', null, 'Guard Pull vers Collar-Sleeve (Col-Manche).', 'document'),
  ('FC1-2', 'FC1', 2, 'FC1-1', 'action', null, 'Vous menacez le Triangle ou l''Omoplata.', 'document'),
  ('FC1-3', 'FC1', 3, 'FC1-2', 'reaction', null, 'Il recule et redresse sa posture pour défendre le haut du corps.', 'document'),
  ('FC1-4', 'FC1', 4, 'FC1-3', 'transition', null, 'Passage en De La Riva (DLR) en accrochant sa jambe avant.', 'document'),
  ('FC1-5', 'FC1', 5, 'FC1-4', 'action', null, 'Vous déséquilibrez vers l''arrière pour le Tripod Sweep ou le Berimbolo.', 'document'),
  ('FC1-6', 'FC1', 6, 'FC1-5', 'reaction', null, 'Il plie son genou vers l''intérieur pour écraser votre crochet DLR et tenter un Knee Cut Pass.', 'document'),
  ('FC1-7', 'FC1', 7, 'FC1-6', 'transition', null, 'Bascule en Reverse De La Riva (RDLR).', 'document'),
  ('FC1-8', 'FC1', 8, 'FC1-7', 'action', null, 'Vous inversez sous ses hanches (Kiss of the Dragon) pour exposer son dos.', 'document'),
  ('FC1-9', 'FC1', 9, 'FC1-8', 'finalisation', null, 'Prise de dos (Seatbelt + prise de col) → Bow and Arrow Choke.', 'document'),
  ('FC2-1', 'FC2', 1, null, 'depart', null, 'Entrée en position Headquarters (un pied entre ses jambes, contrôle du pantalon et du col).', 'document'),
  ('FC2-2', 'FC2', 2, 'FC2-1', 'action', null, 'Vous lancez un Torreando Pass sur le côté pour contourner les jambes.', 'document'),
  ('FC2-3', 'FC2', 3, 'FC2-2', 'reaction', null, 'Il tourne ses hanches vers vous et lève les jambes pour bloquer votre passage.', 'document'),
  ('FC2-4', 'FC2', 4, 'FC2-3', 'transition', null, 'Changement d''angle vers le Knee Cut Pass à l''opposé (en tirant fort son col pour coller son dos au tapis).', 'document'),
  ('FC2-5', 'FC2', 5, 'FC2-4', 'reaction', null, 'Il insère un bouclier de genou (Knee Shield) ou ferme la demi-garde.', 'document'),
  ('FC2-6', 'FC2', 6, 'FC2-5', 'transition', null, 'Écrasement en Smash Pass ou Over-Under Pass pour neutraliser ses hanches.', 'document'),
  ('FC2-7', 'FC2', 7, 'FC2-6', 'finalisation', null, 'Contrôle latéral (Crossface) → Passage en montée → Cross Collar Choke ou Armbar.', 'document'),
  ('FC3-d', 'FC3', 1, null, 'depart', null, 'Seated Guard (Garde assise) avec bataille de mains (Hand Fighting).', 'document'),
  ('FC3-a1', 'FC3', 2, 'FC3-d', 'action', null, 'Vous attaquez un Arm Drag ou un Butterfly Sweep.', 'document'),
  ('FC3-ra', 'FC3', 3, 'FC3-a1', 'reaction', 'Réaction A : il recule', 'Réaction A (Il recule) : Vous déclenchez un Wrestle-Up (Single Leg) pour le faire tomber et passer au-dessus.', 'document'),
  ('FC3-pa', 'FC3', 4, 'FC3-ra', 'transition', null, 'Après le Wrestle-Up, finir la chute puis passer la garde avec le Body Lock Pass ; s''il tourne le dos pour se relever, Seatbelt puis Rear Naked Choke.', 'proposition'),
  ('FC3-rb', 'FC3', 5, 'FC3-a1', 'reaction', 'Réaction B : il avance et met son poids sur vous', 'Réaction B (Il avance et met son poids sur vous) : Vous glissez sous lui pour entrer en Single Leg X (SLX) ou K-Guard.', 'document'),
  ('FC3-t', 'FC3', 6, 'FC3-rb', 'transition', null, 'Déséquilibre depuis SLX / X-Guard.', 'document'),
  ('FC3-a2', 'FC3', 7, 'FC3-t', 'action', null, 'Vous le forcez à poser les mains au tapis, exposant son talon.', 'document'),
  ('FC3-f', 'FC3', 8, 'FC3-a2', 'finalisation', null, 'Entrée en Saddle (4/11) ou Backside 50/50 → Inside Heel Hook.', 'document'),
  ('FC3-alt', 'FC3', 9, 'FC3-f', 'alternative', 'S''il cache son talon', '(Alternative si il cache son talon :) Vous remontez dans son dos via Crab Ride → Rear Naked Choke.', 'document'),
  ('FC4-d', 'FC4', 1, null, 'depart', null, 'Debout → Snap Down vers Front Headlock.', 'document'),
  ('FC4-r1', 'FC4', 2, 'FC4-d', 'reaction', null, 'Il rentre la tête et baisse les coudes pour éviter la Guillotine.', 'document'),
  ('FC4-t1', 'FC4', 3, 'FC4-r1', 'transition', null, 'Vous contournez vers le dos (Slide By) ou vous le forcez au sol pour passer en Body Lock Pass.', 'document'),
  ('FC4-ps', 'FC4', 4, 'FC4-t1', 'transition', 'Slide By', 'Après le contournement, ceinture arrière, retour au sol, puis Seatbelt + Body Triangle et Rear Naked Choke.', 'proposition'),
